const run = $input.first().json;
const steps = run.intermediate_steps || run.intermediateSteps || [];

const clean = value => {
  if (!value) return null;

  let target = value;
  // If it's a stringified JSON object/array, parse it
  if (typeof target === 'string') {
    try {
      target = JSON.parse(target);
    } catch {
      return target;
    }
  }

  // Handle array wrappers like [{"output": "..."}]
  if (Array.isArray(target) && target.length > 0) {
    target = target[0];
  }

  // Extract the inner output string
  if (typeof target === 'object' && target !== null) {
    return target.output ?? target.response ?? target.text ?? JSON.stringify(target);
  }

  return String(target);
};

const resultOf = word => {
  const step = steps.filter(s => {
    const actionName = s.action?.tool || s.action?.name || s.tool || '';
    return String(actionName).toLowerCase().includes(word);
  }).pop();

  if (!step) return null;
  return clean(step.observation || step.output || step.log);
};

const sections = [
  ['Match Analysis', resultOf('matcher') || resultOf('cv'), 'CV Matcher'],
  ['Tailored Cover Letter', resultOf('letter') || resultOf('cover'), 'Cover Letter Writer'],
  ['Interview Preparation', resultOf('interview'), 'Interview Coach'],
];

const mainOutput = clean(run.output || run.text || '');

const report = [mainOutput]
  .concat(sections.map(([title, body, agent]) => 
    '## ' + title + '\n\n' + (body || '_The ' + agent + ' did not run this time. Please submit the form again._')
  ))
  .join('\n\n');

return [{ json: { report, specialistsUsed: sections.filter(s => s[1]).length } }];

